class Solution:
    def findPermutation(self, nums: List[int]) -> List[int]:
        n = len(nums)
        FULL = (1 << n) - 1
        INF = float('inf')
        g = [[INF] * n for _ in range(1 << n)]
        for last in range(n):
            g[FULL][last] = abs(last - nums[0])
        for mask in range(FULL - 1, 0, -1):
            if not mask & 1:
                continue
            for last in range(n):
                if not (mask >> last) & 1:
                    continue
                b = INF
                for nxt in range(n):
                    if (mask >> nxt) & 1:
                        continue
                    c = abs(last - nums[nxt]) + g[mask | (1 << nxt)][nxt]
                    if c < b:
                        b = c
                g[mask][last] = b
        res = []
        mask, last = 1, 0
        while mask != FULL:
            for nxt in range(n):
                if (mask >> nxt) & 1:
                    continue
                if abs(last - nums[nxt]) + g[mask | (1 << nxt)][nxt] == g[mask][last]:
                    res.append(nxt)
                    mask |= 1 << nxt
                    last = nxt
                    break
        return [0] + res

