class Solution {
public:
    vector<int> findPermutation(vector<int>& nums) {
        int n = nums.size(), FULL = (1 << n) - 1;
        vector<vector<int>> g(1 << n, vector<int>(n, INT_MAX / 2));
        for (int last = 0; last < n; last++) g[FULL][last] = abs(last - nums[0]);
        for (int mask = FULL - 1; mask >= 1; mask--) {
            if (!(mask & 1)) continue;
            for (int last = 0; last < n; last++) {
                if (!((mask >> last) & 1)) continue;
                for (int nxt = 0; nxt < n; nxt++) {
                    if ((mask >> nxt) & 1) continue;
                    g[mask][last] = min(g[mask][last], abs(last - nums[nxt]) + g[mask | (1 << nxt)][nxt]);
                }
            }
        }
        vector<int> res;
        int mask = 1, last = 0;
        while (mask != FULL) {
            for (int nxt = 0; nxt < n; nxt++) {
                if ((mask >> nxt) & 1) continue;
                if (abs(last - nums[nxt]) + g[mask | (1 << nxt)][nxt] == g[mask][last]) {
                    res.push_back(nxt);
                    mask |= 1 << nxt;
                    last = nxt;
                    break;
                }
            }
        }
        res.insert(res.begin(), 0);
        return res;
    }
};

