class Solution {
    public int[] findPermutation(int[] nums) {
        int n = nums.length, FULL = (1 << n) - 1;
        int[][] g = new int[1 << n][n];
        for (int[] row : g) java.util.Arrays.fill(row, Integer.MAX_VALUE / 2);
        for (int last = 0; last < n; last++) g[FULL][last] = Math.abs(last - nums[0]);
        for (int mask = FULL - 1; mask >= 1; mask--) {
            if ((mask & 1) == 0) continue;
            for (int last = 0; last < n; last++) {
                if ((mask & (1 << last)) == 0) continue;
                for (int nxt = 0; nxt < n; nxt++) {
                    if ((mask & (1 << nxt)) != 0) continue;
                    g[mask][last] = Math.min(g[mask][last], Math.abs(last - nums[nxt]) + g[mask | (1 << nxt)][nxt]);
                }
            }
        }
        int[] res = new int[n];
        res[0] = 0;
        int mask = 1, last = 0;
        for (int idx = 1; idx < n; idx++) {
            for (int nxt = 0; nxt < n; nxt++) {
                if ((mask & (1 << nxt)) != 0) continue;
                if (Math.abs(last - nums[nxt]) + g[mask | (1 << nxt)][nxt] == g[mask][last]) {
                    res[idx] = nxt;
                    mask |= 1 << nxt;
                    last = nxt;
                    break;
                }
            }
        }
        return res;
    }
}

