var findPermutation = function(nums) {
    const n = nums.length, FULL = (1 << n) - 1;
    const g = Array.from({length: 1 << n}, () => new Array(n).fill(Infinity));
    for (let last = 0; last < n; last++) g[FULL][last] = Math.abs(last - nums[0]);
    for (let mask = FULL - 1; mask >= 1; mask--) {
        if (!(mask & 1)) continue;
        for (let last = 0; last < n; last++) {
            if (!((mask >> last) & 1)) continue;
            for (let nxt = 0; nxt < n; nxt++) {
                if ((mask >> nxt) & 1) continue;
                const c = Math.abs(last - nums[nxt]) + g[mask | (1 << nxt)][nxt];
                if (c < g[mask][last]) g[mask][last] = c;
            }
        }
    }
    const res = [0];
    let mask = 1, last = 0;
    while (mask !== FULL) {
        for (let nxt = 0; nxt < n; nxt++) {
            if ((mask >> nxt) & 1) continue;
            if (Math.abs(last - nums[nxt]) + g[mask | (1 << nxt)][nxt] === g[mask][last]) {
                res.push(nxt);
                mask |= 1 << nxt;
                last = nxt;
                break;
            }
        }
    }
    return res;
};
